<?php
/**
 * Layout Designer training hub: the [lug_demo_training] shortcode.
 *
 * Data comes from fixtures/training-videos.php, generated by
 * lug-layout-designer/scripts/training/export-hub-data.mjs. A topic without an
 * uploaded video for the chosen voice links to that voice's playlist instead.
 *
 * @package LUG_Demo
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

final class LUG_Demo_Training {
	public function hooks() {
		add_shortcode( 'lug_demo_training', array( $this, 'render' ) );
	}

	private function data() {
		$file = LUG_DEMO_DIR . 'fixtures/training-videos.php';
		$data = file_exists( $file ) ? (array) require $file : array();
		return wp_parse_args( $data, array( 'channel' => '', 'voices' => array(), 'topics' => array() ) );
	}

	public function render() {
		$data   = $this->data();
		$voices = (array) $data['voices'];
		if ( empty( $voices ) || empty( $data['topics'] ) ) {
			return '';
		}

		$voice = isset( $_GET['voice'] ) ? sanitize_text_field( wp_unslash( $_GET['voice'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only display choice.
		if ( ! isset( $voices[ $voice ] ) ) {
			$voice = (string) array_key_first( $voices );
		}
		$playlist_url = 'https://www.youtube.com/playlist?list=' . rawurlencode( $voices[ $voice ] );

		$output = '<div class="lug-demo-training">';

		// Voice choice.
		$output .= '<nav class="lug-demo-training-voices" aria-label="' . esc_attr__( 'Narrator voice', 'lug-demo' ) . '"><span>' . esc_html__( 'Narrator:', 'lug-demo' ) . '</span>';
		foreach ( array_keys( $voices ) as $name ) {
			$current = $name === $voice;
			$output .= '<a href="' . esc_url( add_query_arg( 'voice', $name ) ) . '"' . ( $current ? ' aria-current="true" class="is-current"' : '' ) . '>' . esc_html( $name ) . '</a>';
		}
		$output .= '</nav>';

		// Start here: episode 1 in the chosen voice.
		$first = reset( $data['topics'] );
		if ( ! empty( $first['videos'][ $voice ] ) ) {
			$output .= '<section class="lug-demo-training-start"><h2>' . esc_html__( 'Start here', 'lug-demo' ) . '</h2>';
			$output .= '<div class="lug-demo-training-player"><iframe src="' . esc_url( 'https://www.youtube-nocookie.com/embed/' . rawurlencode( $first['videos'][ $voice ] ) . '?list=' . rawurlencode( $voices[ $voice ] ) . '&rel=0' ) . '" title="' . esc_attr( $first['title'] ) . '" loading="lazy" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen></iframe></div>';
			$output .= '<p>' . esc_html( $first['summary'] ) . '</p></section>';
		}

		// Every topic in order.
		$output .= '<section class="lug-demo-training-topics"><h2>' . esc_html__( 'All episodes', 'lug-demo' ) . '</h2><ol>';
		$list_items = array();
		foreach ( $data['topics'] as $topic ) {
			$video_id = isset( $topic['videos'][ $voice ] ) ? $topic['videos'][ $voice ] : '';
			$url      = $video_id ? 'https://www.youtube.com/watch?v=' . rawurlencode( $video_id ) . '&list=' . rawurlencode( $voices[ $voice ] ) : $playlist_url;
			$output  .= '<li value="' . (int) $topic['number'] . '"><h3>' . esc_html( $topic['title'] ) . '</h3><p>' . esc_html( $topic['summary'] ) . '</p>';
			$output  .= $video_id
				? '<a class="lug-demo-training-watch" href="' . esc_url( $url ) . '">' . esc_html__( 'Watch on YouTube', 'lug-demo' ) . '</a>'
				: '<span class="lug-demo-training-soon">' . esc_html__( 'Coming soon in this voice.', 'lug-demo' ) . '</span> <a href="' . esc_url( $playlist_url ) . '">' . esc_html__( 'Open the playlist', 'lug-demo' ) . '</a>';
			$output  .= '</li>';
			if ( $video_id ) {
				$list_items[] = array(
					'@type'    => 'ListItem',
					'position' => (int) $topic['number'],
					'name'     => $topic['title'],
					'url'      => 'https://www.youtube.com/watch?v=' . $video_id,
				);
			}
		}
		$output .= '</ol></section>';

		$output .= '<section class="lug-demo-training-next"><h2>' . esc_html__( 'Try it yourself', 'lug-demo' ) . '</h2><p>' . esc_html__( 'Log in with a demo account and open the Layout Designer to follow along. Nothing you change here is permanent.', 'lug-demo' ) . '</p><p><a href="' . esc_url( home_url( '/layout/' ) ) . '">' . esc_html__( 'Open the Layout Designer', 'lug-demo' ) . '</a> · <a href="' . esc_url( $playlist_url ) . '">' . esc_html( sprintf( /* translators: %s: narrator name */ __( 'Full playlist (%s)', 'lug-demo' ), $voice ) ) . '</a></p></section>';

		if ( $list_items ) {
			$output .= '<script type="application/ld+json">' . wp_json_encode(
				array(
					'@context'        => 'https://schema.org',
					'@type'           => 'ItemList',
					'name'            => 'LUG Layout Designer training videos',
					'itemListElement' => $list_items,
				)
			) . '</script>';
		}

		return $output . '</div>';
	}
}
